{{ (async()=>{try{
 const capacity=selIndividualContactCapacity.selectedOptionValue;
 const row=((selIndividualContactCapacity.selectedOptionValue === 'member' ? qIndividualMembershipContacts.data : qIndividualDonorContacts.data) || []).find(c=>c.contact_id===selIndividualRoleContactToArchive.selectedOptionValue && c.contact_kind==='email');
 if(!row) {showAlert('Select an email first.','warning');return;}
 if(capacity==='member'){
   if(row.mailing_subscription_status==='subscribed'){await qUnsubscribeIndividualEmail.run();showAlert('Membership email unsubscribe requested.','success');}
   else {await qSubscribeIndividualEmail.run();showAlert('Membership email subscription requested.','success');}
   await Promise.all([qIndividualMembershipContacts.run(),qIndividualContacts.run()]);
 } else if(capacity==='contributor') {
   const r=await qToggleIndividualContributorEmailSubscription.run();
   if(!r?.[0]?.queue_id) throw new Error('Contributor Listmonk synchronization was not queued.');
   showAlert(r[0].mailing_subscription_status==='subscribed'?'Contributor mailing subscription queued.':'Contributor mailing unsubscribe queued.','success');
   await Promise.all([qIndividualDonorContacts.run(),qIndividualContacts.run()]);
 } else {showAlert('Select an email capacity first.','warning');}
}catch(e){showAlert('Mailing subscription change failed: '+(e?.message||e),'error');}})() }}
